import React, { useState, useEffect } from 'react'
import './GroupCard.scss'
import axios from 'axios';
import { Pencil, Trash2 } from 'lucide-react'

const GroupCard = () => {
    const [groups, setGroups] = useState({})

    const handleRemoveClick = async (groupName) => {
        try {
            await axios.delete(`http://localhost:8800/group/${groupName}`)
            getGroups()
        } catch (error) {
            console.error(`Failed to delete group`)
        }
    }

    const getGroups = async () => {
        try {
            const response = await axios.get('http://localhost:8800/groups');
            setGroups(response.data); // Assuming response.data contains your groups data
        } catch (error) {
            console.error('Failed to fetch data', error);
        }
    }

    useEffect(() => {
        getGroups()
    }, [])

    return (
        <div className='group-card-container'>
            {Object.keys(groups).map(groupName => (
                <div className='card-section' key={groupName}>
                    <h2 className='group-name'>{groupName}</h2>
                    <Trash2 className='remove-group-button' onClick={() => handleRemoveClick(groupName)}/>
                    <p className='group-description'>{groups[groupName].description}</p>
                    <div className='card-body-section'>
                        <button className='edit-group-button'>
                            <Pencil/>
                        </button>
                    </div>
                </div>
            ))}
        </div>
    )
}

export default GroupCard
